// One pending capture at most; stopping drains it without scheduling another.
export class CaptureSequence {
 constructor(shoot,changed=()=>{},failed=()=>{},schedule=(fn,delay)=>setTimeout(fn,delay),cancel=id=>clearTimeout(id)){
  Object.assign(this,{shoot,changed,failed,schedule,cancel,running:false,pending:null,saved:0,generation:0});
 }
 take(){
  if(this.pending)return this.pending;
  this.pending=Promise.resolve().then(this.shoot).then(added=>{if(added)this.saved++;return added;}).finally(()=>{this.pending=null;this.changed();});
  this.changed();return this.pending;
 }
 async start(seconds){
  if(!Number.isFinite(seconds)||seconds<1||seconds>3600)throw new RangeError('capture interval');
  this.stop();this.running=true;const generation=this.generation;this.changed();
  const tick=async()=>{
   try{await this.take();}catch(error){this.stop();throw error;}
   if(this.running&&generation===this.generation)this.timer=this.schedule(()=>tick().catch(this.failed),seconds*1000);
  };
  await tick();
 }
 stop(){this.generation++;this.running=false;this.cancel(this.timer);this.timer=null;this.changed();}
 async finish(){this.stop();await this.pending;}
}

export function captureCameraReady(camera){
 return camera?.status==='online'&&!camera.algorithm_error&&(camera.operating_mode==='preview'?camera.preview_fresh===true:camera.algorithm_fresh!==false&&(!camera.operating_mode||camera.operating_mode==='business'));
}

export function validRatios(values){return values.length===3&&values.every(n=>Number.isInteger(n)&&n>0)&&values.reduce((a,b)=>a+b,0)===100;}
export function moveSplit(values,boundary,value){const r=validRatios(values)?values.slice():[80,10,10];if(boundary===0){const right=r[0]+r[1];r[0]=Math.max(1,Math.min(right-1,Math.round(value)));r[1]=right-r[0];}else{const right=Math.max(r[0]+1,Math.min(99,Math.round(value)));r[1]=right-r[0];r[2]=100-right;}return r;}
export function trainingParameters(size,epochs=100,lr0=.001,batch=null){return {epochs:Number(epochs),lr0:Number(lr0),batch:batch===null?(size==='yolo11n'?4:1):Number(batch)};}
export function trainingProgress(job){return Math.max(0,Math.min(job?.state==='completed'?1:.99,Number.isFinite(job?.progress)?job.progress:0));}
export function trainingMetricRows(job,locale){
 const names={'box_loss':'boxLoss','cls_loss':'classLoss','dfl_loss':'dflLoss','precision(B)':'precision','recall(B)':'recall','mAP50(B)':'map50','mAP50-95(B)':'map5095','fitness':'fitness'};
 const label=key=>tr('studio.'+key,{},locale);
 const rows=[];
 for(const [values,test] of [[{...job.losses,...job.metrics},false],[job.test_metrics||{},true]]){
  for(const [key,value] of Object.entries(values)){
   const name=key.split('/').at(-1),scope=test?'test':key.startsWith('train/')?'train':'validation';
   rows.push({label:label('metricScope.'+scope)+' · '+(names[name]?label('metric.'+names[name]):key),value});
  }
 }
 for(const [key,value] of Object.entries(job.lr||{}))rows.push({label:label('actualLearningRate')+' '+key.split('/').at(-1),value});
 return rows;
}
