 async function poll(){if(!dialog.open||pollBusy)return;pollBusy=true;try{if(Date.now()-lastConfigRead>3000){const next=await request('/api/v1/settings');if(config&&next.revision!==config.revision){E('jobPreviewImage').hidden=true;E('jobPreviewImage').removeAttribute('src');if(!materialDirty&&!modelDirty){config=next;fillMaterials();await refreshModels();}else notify('studio.error.conflict',true);}lastConfigRead=Date.now();}const downloads=(await request('/api/v1/models/downloads')).downloads;renderDownload(downloads);if(downloads.some(d=>d.state==='completed'&&!models.some(m=>m.id===d.model_id)))await refreshModels();await refreshCounts();if(job){job=await request('/api/v1/training/jobs/'+job.id);E('jobStage').textContent=tr('studio.state.'+job.state)+' · '+tr('studio.stage.'+job.stage)+' · '+job.epoch+'/'+job.parameters.epochs+(job.batch_index?' · '+job.batch_index+'/'+job.batches_total+' '+tr('studio.batch'):'')+(job.error?' · '+tr('studio.error.'+job.error):'');E('jobProgress').value=trainingProgress(job);E('jobMetrics').replaceChildren();for(const {label,value:v}of trainingMetricRows(job)){const row=document.createElement('div');row.textContent=label+' '+(typeof v==='number'?(v!==0&&Math.abs(v)<.0001?v.toExponential(3):v.toFixed(4)):String(v));E('jobMetrics').append(row);}for(const [k,label]of [['elapsed_seconds','elapsed'],['eta_seconds','eta']])if(Number.isFinite(job[k])){const row=document.createElement('div');row.textContent=tr('studio.'+label)+' '+Math.round(job[k])+'s';E('jobMetrics').append(row);}if(Number.isFinite(job.peak_memory_allocated_bytes)){const row=document.createElement('div');row.textContent=tr('studio.peakMemory')+' '+(job.peak_memory_allocated_bytes/1024/1024).toFixed(0)+' MiB';E('jobMetrics').append(row);}E('jobLog').textContent=job.log||'';E('jobPreview').disabled=E('jobDeploy').disabled=job.state!=='completed';E('jobResume').disabled=!['paused','interrupted','failed'].includes(job.state)||!job.checkpoint;E('jobStop').disabled=E('jobCancel').disabled=!['queued','preparing','running','validating','saving','stopping'].includes(job.state);}}catch(e){fail(e);}finally{pollBusy=false;}}
 setInterval(poll,1000);setInterval(syncCapturePreview,1000);window.addEventListener('pagehide',suspendCapture);window.addEventListener('worktime-settings-hidden',()=>{suspendCapture();if(dialog.open)dialog.close();});let visibilityTimer;document.addEventListener('visibilitychange',()=>{clearTimeout(visibilityTimer);if(document.hidden)visibilityTimer=setTimeout(()=>{if(document.hidden)suspendCapture();},150);});window.addEventListener('languagechange',()=>{translatePage();modelOptions();renderRules();updateGroup();updateCaptureUI();renderRecent();syncCapturePreview();drawSplit();refreshDatasets().catch(fail);loadSnapshots().catch(fail);refreshJobs().then(poll).catch(fail);});window.addEventListener('resize',()=>{materialEditor.draw();annotator.draw();});
